#!/usr/bin/env python3
"""Reviewed validator-only amendment: prove hoisted constants from real CFG."""
import base64,hashlib,json,lzma,subprocess,sys
from pathlib import Path
DATA=''
EXPECTED='90b98e1b90ed909bed74646de06f2feed5cb95ec32ba1e3eeb7b2e5895af412a'
def sha(b):return hashlib.sha256(b).hexdigest()
R=Path(sys.argv[1]);raw=base64.b64decode(DATA,validate=True);assert sha(raw)==EXPECTED
changes=json.loads(lzma.decompress(raw))
for n,row in changes.items():
 p=R/n;assert not Path(n).is_absolute() and '..' not in Path(n).parts
 if row['old'] is None:assert not p.exists();p.write_text(row['text'])
 else:
  assert sha(p.read_bytes())==row['old'],n
  subprocess.run(['patch','-p1','--batch','--forward'],cwd=R,input=row['patch'],text=True,check=True)
 assert sha(p.read_bytes())==row['sha256'],n
here=R/'fix1910/amend1910.py';assert not here.exists();here.write_bytes(Path(__file__).read_bytes())
manifest=R/'fix1910/overlay-files.json';pins=json.loads(manifest.read_text())
for n in changes:pins[n]=sha((R/n).read_bytes())
pins['fix1910/amend1910.py']=sha(here.read_bytes());manifest.write_text(json.dumps(pins,sort_keys=True,indent=2)+'\n')
for n,h in pins.items():assert sha((R/n).read_bytes())==h,n
print('PASS_VALIDATOR_FLOW_AMENDMENT pinned files=',len(pins))
